"""Contrôles des sources ST de plc/src sans compilateur TwinCAT (ils ne le remplacent pas).

    python3 tools/plc/check_st.py [dossier]      (par défaut plc/src)

1. doublons  : identifiants déclarés deux fois dans une méthode, à la casse près (ST ne distingue pas I de i)
2. acces     : variable interne (VAR) d'un bloc lue ou écrite depuis l'extérieur
3. chaines   : membre inexistant dans une chaîne a.b[i].c (blocs, interfaces, structures, GVL)
4. arguments : nombre ou noms d'arguments d'un appel de méthode ou de fonction
"""
import pathlib, subprocess, sys

ROOT = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else pathlib.Path(__file__).resolve().parents[2] / 'plc' / 'src')
CHECKS = {'doublons': "import re, sys, pathlib\n# Signale, par méthode, les identifiants déclarés deux fois sans tenir compte de la casse (ST est insensible à la casse)\nfor p in sys.argv[1:]:\n    txt = pathlib.Path(p).read_text(encoding='utf-8')\n    txt = re.sub(r'//.*', '', txt)\n    txt = re.sub(r'\\(\\*.*?\\*\\)', '', txt, flags=re.S)\n    blocks = re.split(r'^(?=METHOD|PROPERTY|FUNCTION_BLOCK|FUNCTION )', txt, flags=re.M)\n    fbvars = set()\n    for b in blocks:\n        head = b.split('\\n',1)[0].strip()\n        decls = []\n        for m in re.finditer(r'^\\s*VAR\\w*(?:\\s+PERSISTENT)?\\s*$(.*?)^\\s*END_VAR', b, flags=re.M|re.S):\n            for line in m.group(1).split('\\n'):\n                mm = re.match(r'\\s*([A-Za-z_]\\w*)\\s*:', line)\n                if mm: decls.append(mm.group(1))\n        low = [d.lower() for d in decls]\n        if head.startswith('FUNCTION_BLOCK'):\n            fbvars = set(low)\n        dups = {d for d in low if low.count(d) > 1}\n        # nom de la méthode = variable de retour\n        mname = re.match(r'(?:METHOD|PROPERTY)\\s+(?:PRIVATE\\s+|PROTECTED\\s+|PUBLIC\\s+)?(\\w+)', head)\n        if mname and mname.group(1).lower() in low:\n            dups.add(mname.group(1).lower()+' (nom de méthode)')\n        if dups:\n            print(p, head[:60], sorted(dups))\n", 'acces': "import re, sys, pathlib\n# Signale les accès « instance.membre » où le membre est une variable interne (VAR) d'un bloc fonctionnel :\n# en ST, seules les entrées, sorties, méthodes et propriétés sont accessibles de l'extérieur.\nroot = pathlib.Path(sys.argv[1])\nfiles = list(root.rglob('*.st'))\ndef strip(t):\n    t = re.sub(r'//.*', '', t)\n    return re.sub(r'\\(\\*.*?\\*\\)', '', t, flags=re.S)\nfbs = {}\nfor f in files:\n    t = strip(f.read_text(encoding='utf-8'))\n    m = re.match(r'\\s*FUNCTION_BLOCK\\s+(\\w+)(?:\\s+EXTENDS\\s+(\\w+))?', t)\n    if not m: continue\n    name, base = m.group(1), m.group(2)\n    head = re.split(r'^(?:METHOD|PROPERTY)\\b', t, flags=re.M)[0]\n    internal, public = set(), set()\n    for vm in re.finditer(r'^\\s*(VAR(?:_INPUT|_OUTPUT|_IN_OUT)?)\\b[^\\n]*$(.*?)^\\s*END_VAR', head, flags=re.M|re.S):\n        kind = vm.group(1)\n        for line in vm.group(2).split('\\n'):\n            mm = re.match(r'\\s*([A-Za-z_]\\w*)\\s*:', line)\n            if mm:\n                (public if kind != 'VAR' else internal).add(mm.group(1).lower())\n    members = {m.group(1).lower() for m in re.finditer(r'^(?:METHOD|PROPERTY)\\s+(?:PRIVATE\\s+|PROTECTED\\s+|PUBLIC\\s+|INTERNAL\\s+)?(\\w+)', t, flags=re.M)}\n    fbs[name.lower()] = dict(base=(base or '').lower(), internal=internal, public=public|members)\ndef resolve(fb):\n    internal, public = set(), set()\n    while fb in fbs:\n        internal |= fbs[fb]['internal']; public |= fbs[fb]['public']; fb = fbs[fb]['base']\n    return internal - public\nfor f in files:\n    t = strip(f.read_text(encoding='utf-8'))\n    decl = {}\n    for m in re.finditer(r'^\\s*(\\w+)\\s*:\\s*(?:REFERENCE TO\\s+|POINTER TO\\s+)?(?:ARRAY\\s*\\[[^\\]]*\\]\\s*OF\\s+(?:POINTER TO\\s+)?)?(FB_\\w+)', t, flags=re.M):\n        decl[m.group(1).lower()] = m.group(2).lower()\n    for var, fb in decl.items():\n        bad = resolve(fb)\n        for m in re.finditer(r'\\b' + re.escape(var) + r'(?:\\[[^\\]]*\\])?\\^?\\.(\\w+)', t, flags=re.I):\n            if m.group(1).lower() in bad:\n                line = t[:m.start()].count('\\n') + 1\n                print(f'{f}:{line}: {var}.{m.group(1)} ({fb})')\n", 'chaines': 'import re, sys, pathlib\n# Vérifie les chaînes d\'accès « a.b[i].c » : chaque membre doit exister dans le type du maillon précédent\n# (blocs, interfaces, structures, GVL). Les types inconnus (bibliothèques Beckhoff) arrêtent la vérification.\nroot = pathlib.Path(sys.argv[1])\nfiles = list(root.rglob(\'*.st\'))\ndef strip(t):\n    t = re.sub(r"\'[^\'\\n]*\'", "\'\'", t)\n    t = re.sub(r\'//.*\', \'\', t)\n    return re.sub(r\'\\(\\*.*?\\*\\)\', \'\', t, flags=re.S)\nTYPEPAT = r\'(?:REFERENCE TO\\s+|POINTER TO\\s+)?(?:ARRAY\\s*\\[[^\\]]*\\]\\s*OF\\s+(?:POINTER TO\\s+|REFERENCE TO\\s+)?)?(\\w+)\'\ntypes = {}   # nom -> (bases, {membre: type ou None})\ndef parse_vars(text):\n    d = {}\n    for line in text.split(\'\\n\'):\n        mm = re.match(r\'\\s*([A-Za-z_]\\w*)\\s*:\\s*\' + TYPEPAT, line)\n        if mm: d[mm.group(1).lower()] = mm.group(2).lower()\n    return d\nfor f in files:\n    t = strip(f.read_text(encoding=\'utf-8\'))\n    m = re.match(r\'\\s*(?:\\{[^}]*\\}\\s*)*(FUNCTION_BLOCK|INTERFACE|TYPE|VAR_GLOBAL)\\s*(\\w*)(?:\\s*:)?(?:\\s+EXTENDS\\s+(\\w+))?(?:\\s+IMPLEMENTS\\s+([\\w, ]+))?\', t)\n    if not m: continue\n    kind = m.group(1)\n    if kind == \'VAR_GLOBAL\':\n        name = f.stem\n        types[name.lower()] = ([], parse_vars(t))\n        continue\n    name = m.group(2)\n    bases = [b.strip().lower() for b in ((m.group(3) or \'\') + \',\' + (m.group(4) or \'\')).split(\',\') if b.strip()]\n    if kind == \'TYPE\':\n        if \'STRUCT\' not in t: continue\n        types[name.lower()] = (bases, parse_vars(t))\n        continue\n    head = re.split(r\'^(?:METHOD|PROPERTY)\\b\', t, flags=re.M)[0]\n    mem = {}\n    for vm in re.finditer(r\'^\\s*VAR\\w*\\b[^\\n]*$(.*?)^\\s*END_VAR\', head, flags=re.M|re.S):\n        mem.update(parse_vars(vm.group(1)))\n    for mm in re.finditer(r\'^(?:METHOD|PROPERTY)\\s+(?:PRIVATE\\s+|PROTECTED\\s+|PUBLIC\\s+|INTERNAL\\s+)?(\\w+)(?:\\s*:\\s*\' + TYPEPAT + \')?\', t, flags=re.M):\n        mem[mm.group(1).lower()] = (mm.group(2) or \'\').lower() or None\n    types[name.lower()] = (bases, mem)\ndef member(tn, mname, seen=None):\n    seen = seen or set()\n    if tn not in types or tn in seen: return \'UNKNOWN_TYPE\'\n    seen.add(tn)\n    b, m = types[tn]\n    if mname in m: return m[mname]\n    for x in b:\n        r = member(x, mname, seen)\n        if r != \'UNKNOWN_TYPE\' and r != \'MISSING\': return r\n    return \'MISSING\'\nseen_err = set()\nfor f in files:\n    t = strip(f.read_text(encoding=\'utf-8\'))\n    blocks = re.split(r\'^(?=METHOD|PROPERTY|FUNCTION_BLOCK|FUNCTION )\', t, flags=re.M)\n    fbname = None\n    mfb = re.match(r\'\\s*FUNCTION_BLOCK\\s+(\\w+)\', t)\n    if mfb: fbname = mfb.group(1).lower()\n    pos = 0\n    for blk in blocks:\n        off = t.find(blk, pos); pos = off + len(blk)\n        decl = {}\n        if fbname: decl.update({k: v for k, v in (types.get(fbname, ([], {}))[1].items()) if v})\n        for vm in re.finditer(r\'^\\s*VAR\\w*\\b[^\\n]*$(.*?)^\\s*END_VAR\', blk, flags=re.M|re.S):\n            decl.update(parse_vars(vm.group(1)))\n        for g in types:\n            if g.startswith(\'gvl_\'): decl[g] = g\n        for m in re.finditer(r\'(?<![\\w.\\]])([A-Za-z_]\\w*)((?:\\[[^\\[\\]]*(?:\\[[^\\[\\]]*\\][^\\[\\]]*)*\\]|\\^)*(?:\\.\\w+(?:\\[[^\\[\\]]*(?:\\[[^\\[\\]]*\\][^\\[\\]]*)*\\]|\\^|\\(\\))*)+)\', blk):\n            root_name = m.group(1).lower()\n            if root_name not in decl: continue\n            tn = decl[root_name]\n            chain = re.findall(r\'\\.(\\w+)\', re.sub(r\'\\[[^\\[\\]]*(?:\\[[^\\[\\]]*\\][^\\[\\]]*)*\\]\', \'\', m.group(2)))\n            for c in chain:\n                r = member(tn, c.lower())\n                if r == \'UNKNOWN_TYPE\' or r is None: break\n                if r == \'MISSING\':\n                    line = t[:off].count(\'\\n\') + blk[:m.start()].count(\'\\n\') + 1\n                    key = (str(f), line, c)\n                    if key not in seen_err:\n                        seen_err.add(key)\n                        print(f\'{f.relative_to(root)}:{line}: {m.group(0)[:60]} : « {c} » absent de {tn}\')\n                    break\n                tn = r\n', 'arguments': 'import re, sys, pathlib\n# Vérifie les appels de méthodes (inst.M(...)) et de fonctions F_x(...) : nombre d\'arguments positionnels\n# et noms des arguments nommés, contre VAR_INPUT / VAR_IN_OUT / VAR_OUTPUT de la déclaration.\nroot = pathlib.Path(sys.argv[1])\nfiles = list(root.rglob(\'*.st\'))\ndef strip(t):\n    t = re.sub(r"\'[^\'\\n]*\'", "\'\'", t)\n    t = re.sub(r\'//.*\', \'\', t)\n    return re.sub(r\'\\(\\*.*?\\*\\)\', \'\', t, flags=re.S)\nTYPEPAT = r\'(?:REFERENCE TO\\s+|POINTER TO\\s+)?(?:ARRAY\\s*\\[[^\\]]*\\]\\s*OF\\s+(?:POINTER TO\\s+|REFERENCE TO\\s+)?)?(\\w+)\'\ndef sig(text):\n    ins, outs = [], []\n    for vm in re.finditer(r\'^\\s*(VAR_INPUT|VAR_IN_OUT|VAR_OUTPUT)\\b[^\\n]*$(.*?)^\\s*END_VAR\', text, flags=re.M|re.S):\n        for line in vm.group(2).split(\'\\n\'):\n            mm = re.match(r\'\\s*([A-Za-z_]\\w*)\\s*:\', line)\n            if mm: (outs if vm.group(1) == \'VAR_OUTPUT\' else ins).append(mm.group(1).lower())\n    return ins, outs\ntypes, funcs = {}, {}\nfor f in files:\n    t = strip(f.read_text(encoding=\'utf-8\'))\n    m = re.match(r\'\\s*(?:\\{[^}]*\\}\\s*)*(FUNCTION_BLOCK|INTERFACE|FUNCTION)\\s+(\\w+)(?:\\s*:\\s*\\w+)?(?:\\s+EXTENDS\\s+(\\w+))?\', t)\n    if not m: continue\n    kind, name, base = m.group(1), m.group(2).lower(), (m.group(3) or \'\').lower()\n    if kind == \'FUNCTION\':\n        funcs[name] = sig(t); continue\n    meths = {}\n    for mm in re.finditer(r\'^METHOD\\s+(?:PRIVATE\\s+|PROTECTED\\s+|PUBLIC\\s+|INTERNAL\\s+)?(\\w+)[^\\n]*\\n(.*?)(?=^END_METHOD|^METHOD)\', t, flags=re.M|re.S):\n        body = mm.group(2)\n        decl = body.split(\'\\nEND_VAR\')[0] if \'END_VAR\' in body else \'\'\n        # déclaration : jusqu\'au dernier END_VAR avant la première instruction\n        parts = re.split(r\'^(?!\\s*(?:VAR\\w*|END_VAR|[A-Za-z_]\\w*\\s*:|$))\', body, maxsplit=1, flags=re.M)\n        meths[mm.group(1).lower()] = sig(parts[0])\n    head = re.split(r\'^(?:METHOD|PROPERTY)\\b\', t, flags=re.M)[0]\n    var = {}\n    for vm in re.finditer(r\'^\\s*VAR\\w*\\b[^\\n]*$(.*?)^\\s*END_VAR\', head, flags=re.M|re.S):\n        for line in vm.group(1).split(\'\\n\'):\n            mm = re.match(r\'\\s*([A-Za-z_]\\w*)\\s*:\\s*\' + TYPEPAT, line)\n            if mm: var[mm.group(1).lower()] = mm.group(2).lower()\n    types[name] = (base, meths, var, sig(head))\ndef method(tn, mn):\n    while tn in types:\n        if mn in types[tn][1]: return types[tn][1][mn]\n        tn = types[tn][0]\n    return None\ndef split_args(s):\n    depth, cur, out = 0, \'\', []\n    for ch in s:\n        if ch in \'([\': depth += 1\n        if ch in \')]\': depth -= 1\n        if ch == \',\' and depth == 0: out.append(cur); cur = \'\'\n        else: cur += ch\n    if cur.strip(): out.append(cur)\n    return [a.strip() for a in out]\ndef find_call_args(text, start):\n    depth = 0\n    for i in range(start, len(text)):\n        if text[i] == \'(\': depth += 1\n        elif text[i] == \')\':\n            depth -= 1\n            if depth == 0: return text[start+1:i]\n    return None\ndef check(f, line, label, s, args):\n    ins, outs = s\n    named = [a for a in args if re.match(r\'\\w+\\s*(:=|=>)\', a)]\n    if named:\n        for a in named:\n            n = re.match(r\'(\\w+)\', a).group(1).lower()\n            if n not in ins and n not in outs: print(f\'{f}:{line}: {label} : argument « {n} » inconnu\')\n    elif len(args) != len(ins):\n        print(f\'{f}:{line}: {label} : {len(args)} arguments, {len(ins)} attendus\')\nfor f in files:\n    t = strip(f.read_text(encoding=\'utf-8\'))\n    mfb = re.match(r\'\\s*FUNCTION_BLOCK\\s+(\\w+)\', t)\n    fbn = mfb.group(1).lower() if mfb else None\n    for blk_m in re.finditer(r\'^(?:METHOD|PROPERTY|FUNCTION_BLOCK|FUNCTION )[^\\n]*\\n(.*?)(?=^METHOD|^PROPERTY|^END_FUNCTION_BLOCK|\\Z)\', t, flags=re.M|re.S):\n        blk = blk_m.group(0); off = blk_m.start()\n        decl = dict(types[fbn][2]) if fbn in types else {}\n        for vm in re.finditer(r\'^\\s*VAR\\w*\\b[^\\n]*$(.*?)^\\s*END_VAR\', blk, flags=re.M|re.S):\n            for line in vm.group(1).split(\'\\n\'):\n                mm = re.match(r\'\\s*([A-Za-z_]\\w*)\\s*:\\s*\' + TYPEPAT, line)\n                if mm: decl[mm.group(1).lower()] = mm.group(2).lower()\n        for m in re.finditer(r\'(?<![\\w.])(\\w+)(?:\\[[^\\]]*\\])?\\^?\\.(\\w+)\\s*\\(\', blk):\n            v, mn = m.group(1).lower(), m.group(2).lower()\n            if v not in decl: continue\n            s = method(decl[v], mn)\n            if s is None: continue\n            a = find_call_args(blk, m.end() - 1)\n            if a is None: continue\n            check(f.relative_to(root), t[:off].count(\'\\n\') + blk[:m.start()].count(\'\\n\') + 1, f\'{m.group(1)}.{m.group(2)}\', s, split_args(a))\n        for m in re.finditer(r\'(?<![\\w.])(F_\\w+|_\\w+)\\s*\\(\', blk):\n            n = m.group(1).lower()\n            s = funcs.get(n) or (method(fbn, n) if fbn else None)\n            if s is None: continue\n            a = find_call_args(blk, m.end() - 1)\n            if a is None: continue\n            check(f.relative_to(root), t[:off].count(\'\\n\') + blk[:m.start()].count(\'\\n\') + 1, m.group(1), s, split_args(a))\n'}

def main():
    files = [str(p) for p in ROOT.rglob('*.st')]
    found = False
    for name, code in CHECKS.items():
        args = files if name == 'doublons' else [str(ROOT)]
        r = subprocess.run([sys.executable, '-c', code] + args, capture_output=True, text=True)
        lines = sorted(set(l for l in r.stdout.splitlines() if l.strip()))
        if r.returncode != 0:
            print(f'[{name}] erreur du contrôle :', r.stderr.strip()); found = True
        for l in lines:
            print(f'[{name}] {l}'); found = True
    if not found:
        print('Aucun problème trouvé.')
    return 1 if found else 0

if __name__ == '__main__':
    sys.exit(main())
